/**
 * The proposed fight engine, for simulation only (Claude L, 21 Oct). A PROPOSAL.
 *
 * It extends today's card engine (`lib/battle.ts`) with the folk's signature cards and
 * passives, the familiar's rested special, card variants and ring rivals
 * (`lib/fight-content.ts`), plus the spar fixes F1 and F3 to F5 as switches. The game does
 * not import it: `lib/battle.ts` stays the rule until Matt decides. Everything here is
 * deterministic for a given seed, so the balance report can be regenerated byte for byte.
 */
import { cards as habitCards, isCardId, type CardId } from '@/lib/cards';
import {
  familySpecies,
  folk as allFolk,
  restedSpecials,
  type Family,
  type Folk,
  type PassiveId,
  type Rival,
  type SignatureCard,
} from '@/lib/fight-content';

export type Side = 'a' | 'd';

/** A card as the engine reads it: habit cards and signature cards in one shape. */
export type Card = SignatureCard & {
  habit: Family | null;
  skipChance?: number;
  signature: boolean;
};

const speciesFamily: Record<string, Family> = { BLOB: 'REST', RAT: 'ROAM', CUBE: 'FOCUS' };
/** Passive numbers by id (a rival's passive reads the same numbers as the folk's). */
const passiveN: Partial<Record<PassiveId, Record<string, number>>> = {};
for (const f of allFolk) passiveN[f.passive.id] = f.passive.n;
const pn = (id: PassiveId, key: string) => passiveN[id]?.[key] ?? 0;

export function habitCard(id: CardId): Card {
  const c = habitCards[id];
  const card: Card = {
    id,
    name: c.name,
    cost: c.cost,
    text: c.effect,
    power: c.power || undefined,
    heal: c.heal || undefined,
    habit: c.habit ? speciesFamily[c.habit] : null,
    signature: false,
  };
  if (id === 'deep_breath') Object.assign(card, { guard: true, energyNow: 1 });
  if (id === 'morning_walk') card.energyNext = 1;
  if (id === 'read_a_chapter') card.skipChance = 0.3;
  if (id === 'digital_sunset') card.ignoreGuard = true;
  return card;
}

/** REST beats FOCUS beats ROAM beats REST, 1.5 and 0.67 (today's `matchup`). */
export function matchup(
  source: Family,
  target: Family,
  x: readonly [number, number] = [1.5, 0.67],
) {
  if (source === target) return 1;
  return (source === 'REST' && target === 'FOCUS') ||
    (source === 'FOCUS' && target === 'ROAM') ||
    (source === 'ROAM' && target === 'REST')
    ? x[0]
    : x[1];
}

export type Policy = 'smart' | 'simple' | 'casual';

export type FighterSetup = {
  name: string;
  family: Family;
  level: number;
  zen: number;
  /** Habit card ids. */
  deck: string[];
  folk?: Folk;
  /** Variant picks at 4, 8 and 12: 'a' or 'b' each (only those the level reaches apply). */
  variants?: ('a' | 'b')[];
  /** A rival's single passive (folk bring their own). */
  passive?: PassiveId;
  pips: number;
  policy: Policy;
  /** Presses (F1): x 1.25 on your hits, x 0.75 on hits you take; 1 and 1 with presses off. */
  press?: { attack: number; brace: number };
  /** Today's block button: chance and multiplier (only for the today-engine comparison). */
  block?: { chance: number; x: number };
  mood?: number;
  /** Today's AUTO and Dave: a rolled timing, 20 % PERFECT x 1.5, 20 % WEAK x 0.6. */
  autoTiming?: boolean;
};

/** `computerTiming` in lib/battle.ts. */
export const autoTiming = (roll: number) => (roll < 0.2 ? 1.5 : roll < 0.8 ? 1 : 0.6);

export type Rules = {
  /** F3: a spar that reaches the round limit is a draw (today: your loss). */
  drawAtLimit: boolean;
  roundLimit: number;
  /** A raid against an absent player: Puffcap's doze becomes the softening. */
  raid: boolean;
  /** Advantage and disadvantage multipliers (today 1.5 and 0.67). */
  matchup: readonly [number, number];
  /** Signature cards carry no type: the matchup applies to habit cards only. */
  signatureNeutral: boolean;
  /** With the advantage, start the fight with this much more energy (a tempo edge
   *  instead of, or as well as, the damage multiplier). */
  advantageEnergy: number;
  /** With the advantage, your first damaging card of the fight is multiplied by this
   *  ("super effective", once); 1 for none. */
  advantageFirstHit: number;
  /** A habit card with no power heals 3 instead of the +3 power (today the +3 only adds to
   *  power, so REST, whose habit cards are DEEP BREATH and EARLY NIGHT, never gains it). */
  habitHeal: boolean;
  /** How much of zen counts (today 1; a spar could count a third of it). */
  zenScale: number;
};

export const todayRules: Rules = {
  drawAtLimit: false,
  roundLimit: 12,
  raid: false,
  matchup: [1.5, 0.67],
  signatureNeutral: false,
  advantageEnergy: 0,
  advantageFirstHit: 1,
  habitHeal: false,
  zenScale: 1,
};
/** The proposal for spars (docs/mechanics/fight-content.md): F3's draw, no damage
 *  multiplier between families in a spar (raids keep today's), zen off in spars (F4'),
 *  and the habit heal. */
export const proposedRules: Rules = {
  ...todayRules,
  drawAtLimit: true,
  matchup: [1, 1],
  advantageEnergy: 0,
  advantageFirstHit: 1,
  habitHeal: true,
  zenScale: 0,
};

type Fighter = {
  setup: FighterSetup;
  passive: PassiveId | null;
  table: Record<string, Card>;
  hp: number;
  max: number;
  energy: number;
  nextEnergy: number;
  guardHits: number;
  hand: string[];
  draw: string[];
  discard: string[];
  handLimit: number;
  turns: number;
  stack: number;
  /** Spores on this fighter (from a Puffcap). */
  spores: number;
  /** Pending "a third less" on this fighter's next damaging cards. */
  soften: number;
  /** This fighter's next card costs this much more (Puddle's ebb). */
  soak: number;
  skip: boolean;
  dozed: boolean;
  clock: string | null;
  mend: { amount: number; turns: number } | null;
  lastCard: string | null;
  tideFlip: boolean;
  stillStreak: number;
  muteArmed: boolean;
  reflectArmed: boolean;
  reflectUsed: boolean;
  tricked: boolean;
  bothyUsed: boolean;
  stage: 'deep' | 'dream';
  holdStage: boolean;
  echo: boolean;
  firstHit: boolean;
  pips: number;
  specialUsed: boolean;
  dreamUsed: boolean;
  zonePower: number;
  zoneIgnore: boolean;
  /** Bramble's NOCK makes Steady count this turn. */
  steadyAnyway: boolean;
  dealt: number;
};

export type Fight = {
  a: Fighter;
  d: Fighter;
  rules: Rules;
  rng: () => number;
  round: number;
  result: 'win' | 'loss' | 'draw' | null;
};

export function mulberry32(seed: number) {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function shuffled<T>(items: T[], rng: () => number) {
  const next = [...items];
  for (let i = next.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [next[i], next[j]] = [next[j], next[i]];
  }
  return next;
}

/** The folk's four signature cards with the chosen variants applied. */
export function signatureCards(f: Folk, level: number, picks: ('a' | 'b')[] = []) {
  const out = f.cards.map((c) => ({ ...c }));
  f.variants.forEach((v, i) => {
    if (level < v.level) return;
    const pick = picks[i] === 'b' ? v.b : v.a;
    const at = out.findIndex((c) => c.id === v.card);
    out[at] = { ...out[at], ...pick.patch, name: pick.name };
  });
  return out;
}

function makeFighter(setup: FighterSetup, rng: () => number): Fighter {
  const table: Record<string, Card> = {};
  const deck: string[] = [];
  for (const id of setup.deck) {
    if (!isCardId(id)) continue;
    table[id] ??= habitCard(id);
    deck.push(id);
  }
  if (setup.folk)
    for (const c of signatureCards(setup.folk, setup.level, setup.variants)) {
      table[c.id] = { ...c, habit: null, signature: true };
      deck.push(c.id);
    }
  const max = 60 + 10 * setup.level;
  const f: Fighter = {
    setup,
    passive: setup.folk?.passive.id ?? setup.passive ?? null,
    table,
    hp: max,
    max,
    energy: 1,
    nextEnergy: 0,
    guardHits: 0,
    hand: [],
    draw: shuffled(deck, rng),
    discard: [],
    handLimit: setup.level >= 2 ? 4 : 3,
    turns: 0,
    stack: 0,
    spores: 0,
    soften: 0,
    soak: 0,
    skip: false,
    dozed: false,
    clock: null,
    mend: null,
    lastCard: null,
    tideFlip: false,
    stillStreak: 0,
    muteArmed: false,
    reflectArmed: false,
    reflectUsed: false,
    tricked: false,
    bothyUsed: false,
    stage: 'dream',
    holdStage: false,
    echo: false,
    firstHit: false,
    pips: Math.max(0, Math.min(3, setup.pips)),
    specialUsed: false,
    dreamUsed: false,
    zonePower: 0,
    zoneIgnore: false,
    steadyAnyway: false,
    dealt: 0,
  };
  if (f.passive) f.stack = cap(pn(f.passive, 'start'));
  drawCards(f, f.handLimit, rng);
  return f;
}

function drawCards(f: Fighter, upTo: number, rng: () => number) {
  while (f.hand.length < upTo) {
    if (!f.draw.length) {
      if (!f.discard.length) return;
      f.draw = shuffled(f.discard, rng);
      f.discard = [];
    }
    const card = f.draw.pop();
    if (card) f.hand.push(card);
  }
}

function drawExtra(f: Fighter, n: number, rng: () => number) {
  drawCards(f, f.hand.length + n, rng);
}

export function createFight(a: FighterSetup, d: FighterSetup, rules: Rules, seed: number): Fight {
  const rng = mulberry32(seed);
  const fa = makeFighter(a, rng);
  const fd = makeFighter(d, rng);
  if (rules.advantageEnergy) {
    if (matchup(a.family, d.family) > 1) fa.energy += rules.advantageEnergy;
    if (matchup(d.family, a.family) > 1) fd.energy += rules.advantageEnergy;
  }
  return { a: fa, d: fd, rules, rng, round: 0, result: null };
}

const cap = (n: number) => Math.max(0, Math.min(3, n));
const isDamaging = (c: Card) =>
  (c.power ?? 0) > 0 || !!c.perStack?.power || c.special === 'stardust';

export function cost(f: Fighter, id: string) {
  return f.table[id].cost + f.soak;
}

export type Action = { card: string | null; clock?: boolean; special?: boolean; dream?: boolean };

function tideIsFlow(f: Fighter) {
  return (f.turns % 2 === 0) !== f.tideFlip;
}

/** Apply the familiar's special (or Mote's Dream at half of a full one). Free action. */
function applySpecial(f: Fighter, strengthPips: number, rng: () => number) {
  const s = restedSpecials.find((r) => r.family === f.setup.family);
  if (!s || strengthPips <= 0) return;
  const full = strengthPips >= 3;
  if (s.perPip.heal) f.hp = Math.min(f.max, f.hp + Math.floor(s.perPip.heal * strengthPips));
  if (s.perPip.guard && full) f.guardHits = Math.max(f.guardHits, f.passive === 'bedrock' ? 2 : 1);
  if (s.perPip.refillEnergy) f.energy = Math.min(3, f.energy + Math.floor(strengthPips));
  if (s.perPip.draw && full) drawExtra(f, s.perPip.draw, rng);
  if (s.perPip.power) {
    f.zonePower = Math.floor(s.perPip.power * strengthPips);
    f.zoneIgnore = true;
  }
}

function applyTrick(
  actor: Fighter,
  victim: Fighter,
  kind: 'skip' | 'soak' | 'energy' | 'ignore' | 'spores',
) {
  if (victim.passive !== 'doNotDisturb') return 'apply';
  if (victim.reflectArmed && !victim.reflectUsed) {
    victim.reflectArmed = false;
    victim.muteArmed = false;
    victim.reflectUsed = true;
    victim.tricked = true;
    if (kind === 'skip') actor.skip = true;
    if (kind === 'soak') actor.soak = 1;
    if (kind === 'energy') victim.nextEnergy += 1;
    return 'reflected';
  }
  if (victim.muteArmed) {
    victim.muteArmed = false;
    victim.tricked = true;
    return 'muted';
  }
  return 'apply';
}

function addSpores(actor: Fighter, victim: Fighter, n: number, rules: Rules) {
  if (applyTrick(actor, victim, 'spores') !== 'apply') return;
  victim.spores = cap(victim.spores + n);
  if (victim.spores >= 3) {
    victim.spores = 0;
    if (!rules.raid && !actor.dozed) {
      actor.dozed = true;
      victim.skip = true;
    } else victim.soften += 1;
  }
}

function heal(f: Fighter, amount: number) {
  f.hp = Math.min(f.max, f.hp + Math.max(0, Math.floor(amount)));
}

/** Resolve one card. `scale` is Pendle's clock or Mote's STARDUST. */
function play(fight: Fight, side: Side, card: Card, scale: number, roll: () => number, extra = 0) {
  const actor = fight[side];
  const victim = fight[side === 'a' ? 'd' : 'a'];
  const rng = fight.rng;
  if (card.loseStack) actor.stack = cap(actor.stack - card.loseStack);
  if (card.special === 'flipTide') actor.tideFlip = !actor.tideFlip;
  if (card.special === 'cleanse') {
    actor.soften = 0;
    actor.soak = 0;
    actor.spores = 0;
  }
  if (card.special === 'stardust') {
    const last = actor.lastCard ? actor.table[actor.lastCard] : null;
    // Only the power and the heal come again, at half; no draw, stacks, spores or energy.
    if (last && !['pour', 'stardust'].includes(last.id))
      play(
        fight,
        side,
        {
          id: last.id,
          name: last.name,
          cost: 0,
          text: '',
          power: last.power,
          heal: last.heal,
          ignoreGuard: last.ignoreGuard,
          habit: last.habit,
          signature: last.signature,
        },
        0.5 * scale,
        roll,
      );
    return;
  }
  let healAmount = card.heal ?? 0;
  if (fight.rules.habitHeal && card.habit === actor.setup.family && !card.power) healAmount += 3;
  if (card.perStack?.heal) {
    const n = card.perStack.spendOne ? Math.min(1, actor.stack) : actor.stack;
    healAmount += card.perStack.heal * n;
    if (card.perStack.spend) actor.stack = 0;
    if (card.perStack.spendOne) actor.stack = cap(actor.stack - n);
  }
  if (healAmount) heal(actor, (healAmount + extra) * scale);
  if (card.mend) actor.mend = { ...card.mend };
  if (card.guard) actor.guardHits = Math.max(actor.guardHits, actor.passive === 'bedrock' ? 2 : 1);
  if (card.energyNow) {
    if (applyTrick(actor, victim, 'energy') === 'apply')
      actor.energy = Math.min(3, actor.energy + card.energyNow);
  }
  if (card.energyNext) {
    if (applyTrick(actor, victim, 'energy') === 'apply') actor.nextEnergy += card.energyNext;
  }
  if (card.draw) drawExtra(actor, card.draw, rng);
  if (card.gainStack && !(card.perStack?.spend && card.perStack.heal))
    actor.stack = cap(actor.stack + card.gainStack);
  if (card.spores) addSpores(actor, victim, card.spores, fight.rules);

  if (!isDamaging(card) || !(card.power || card.perStack?.power)) return;
  let power = (card.power ?? 0) + (card.habit && card.habit === actor.setup.family ? 3 : 0);
  if (card.arrow) {
    power += actor.stack * (pn('steady', 'perAim') + (card.perStack?.power ?? 0));
    actor.stack = 0;
  } else if (card.perStack?.power) {
    const n = card.perStack.spendOne ? Math.min(1, actor.stack) : actor.stack;
    power += card.perStack.power * n;
    if (card.perStack.spend) actor.stack = 0;
    if (card.perStack.spendOne) actor.stack = cap(actor.stack - n);
  }
  if (actor.passive === 'bankedFire') power += pn('bankedFire', 'perHeat') * actor.stack;
  if (actor.passive === 'overgrow') power += pn('overgrow', 'perLayer') * actor.stack;
  if (actor.passive === 'tide' && tideIsFlow(actor)) power += card.flowPower ?? pn('tide', 'flow');
  if (card.whileGuarded && actor.guardHits > 0) {
    power += card.whileGuarded.power ?? 0;
    if (card.whileGuarded.energyNext) actor.nextEnergy += card.whileGuarded.energyNext;
    if (card.whileGuarded.spendGuard) actor.guardHits = 0;
  }
  if (card.afterTrick && actor.tricked) power += card.afterTrick;
  if (card.perCardInHand) power += card.perCardInHand * actor.hand.length;
  let ignore = !!card.ignoreGuard;
  if (actor.zonePower) {
    power += actor.zonePower;
    ignore = true;
    actor.zonePower = 0;
    actor.zoneIgnore = false;
  }
  if (card.special === 'removeFoeGuard') ignore = true;
  if (ignore && applyTrick(actor, victim, 'ignore') !== 'apply') ignore = false;
  if (ignore && card.special === 'removeFoeGuard') victim.guardHits = 0;
  if (actor.passive === 'sleepCycle' && actor.echo && scale === 1) {
    actor.echo = false;
    power += pn('sleepCycle', 'echo');
  }
  power += extra;
  if (fight.rules.advantageFirstHit !== 1 && !actor.firstHit) {
    actor.firstHit = true;
    if (matchup(actor.setup.family, victim.setup.family) > 1)
      power *= fight.rules.advantageFirstHit;
  }
  power *= scale;
  const timing = actor.setup.autoTiming ? autoTiming(rng()) : 1;
  const press = (actor.setup.press?.attack ?? 1) * timing;
  const brace = victim.setup.press?.brace ?? 1;
  const blocked =
    victim.setup.block && rng() < victim.setup.block.chance ? victim.setup.block.x : 1;
  let x =
    (card.signature && fight.rules.signatureNeutral
      ? 1
      : matchup(actor.setup.family, victim.setup.family, fight.rules.matchup)) *
    press *
    brace *
    blocked *
    ((actor.setup.mood ?? 80) < 30 ? 0.7 : 1) *
    (victim.guardHits > 0 && !ignore ? 0.5 : 1) *
    (1 - victim.setup.zen * fight.rules.zenScale);
  if (actor.soften > 0) {
    x *= 2 / 3;
    actor.soften -= 1;
  }
  if (victim.passive === 'dim' && victim.stack > 0) {
    x *= 2 / 3;
    victim.stack -= 1;
  }
  const base = power + 2 * actor.setup.level + Math.floor(roll() * 4);
  const amount = Math.max(1, Math.floor(base * x));
  if (victim.guardHits > 0) victim.guardHits -= 1;
  victim.hp -= amount;
  actor.dealt += amount;
  if (victim.passive === 'overgrow' && amount >= pn('overgrow', 'heavy'))
    victim.stack = cap(victim.stack - 1);
  if (victim.hp <= 0 && victim.passive === 'bothy' && !victim.bothyUsed) {
    victim.bothyUsed = true;
    victim.hp = Math.min(victim.max, 1 + pn('bothy', 'healPerWarmth') * victim.stack);
    victim.stack = 0;
  }
  victim.hp = Math.max(0, victim.hp);
  if (actor.passive === 'tide' && !tideIsFlow(actor) && !card.noEbbSoak) {
    if (applyTrick(actor, victim, 'soak') === 'apply') victim.soak = 1;
    if (card.special === 'drainOnEbb') victim.energy = Math.max(0, victim.energy - 1);
  }
  if (card.skipChance && victim.hp > 0 && roll() < card.skipChance)
    if (applyTrick(actor, victim, 'skip') === 'apply') victim.skip = true;
}

/** Apply an action for the side whose turn it is. Returns whether it was a still turn. */
export function act(fight: Fight, side: Side, action: Action, roll: () => number = fight.rng) {
  const f = fight[side];
  if (action.dream && !f.dreamUsed && f.passive === 'dream') {
    f.dreamUsed = true;
    applySpecial(f, 3 * pn('dream', 'strength'), fight.rng);
  }
  if (action.special && !f.specialUsed && f.pips > 0) {
    f.specialUsed = true;
    applySpecial(f, f.pips, fight.rng);
    f.pips = 0;
  }
  let still = true;
  if (action.card) {
    const id = action.card;
    const card = f.table[id];
    f.energy -= cost(f, id);
    f.hand.splice(f.hand.indexOf(id), 1);
    f.discard.push(id);
    if (action.clock) {
      f.clock = id;
      still = !isDamaging(card);
    } else {
      if (card.special === 'nockSteady') f.steadyAnyway = true;
      play(fight, side, card, 1, roll);
      if (isDamaging(card) || card.special === 'pour') still = false;
      if (card.special !== 'stardust') f.lastCard = id;
    }
  } else f.energy = Math.min(3, f.energy + 1);
  f.soak = 0;
  return still;
}

function endTurn(fight: Fight, side: Side, still: boolean) {
  const f = fight[side];
  const foe = fight[side === 'a' ? 'd' : 'a'];
  f.zonePower = 0;
  f.zoneIgnore = false;
  if (f.passive === 'steady' && (f.energy >= 1 || f.steadyAnyway)) f.stack = cap(f.stack + 1);
  f.steadyAnyway = false;
  if (still && ['dim', 'seep', 'countingSheep', 'bothy', 'overgrow'].includes(f.passive ?? ''))
    f.stack = cap(f.stack + 1);
  if (f.passive === 'doNotDisturb') {
    f.stillStreak = still ? f.stillStreak + 1 : 0;
    f.muteArmed = still;
    f.reflectArmed = f.stillStreak >= 2 && !f.reflectUsed;
  }
  if (f.passive === 'sleepCycle') f.holdStage = still;
  // A foe's arming lasts through this side's turn only.
  if (foe.passive === 'doNotDisturb') {
    foe.muteArmed = false;
    foe.reflectArmed = false;
  }
  if (f.hp <= 0 || foe.hp <= 0) {
    const aDown = fight.a.hp <= 0;
    fight.result = aDown ? 'loss' : 'win';
  }
}

/** Start a side's turn. Returns false if the turn is lost (a skip or the bell). */
function beginTurn(fight: Fight, side: Side) {
  const f = fight[side];
  const rng = fight.rng;
  f.turns += 1;
  f.energy = Math.min(3, f.energy + 1 + f.nextEnergy);
  f.nextEnergy = 0;
  if (f.mend) {
    heal(f, f.mend.amount);
    f.mend = f.mend.turns > 1 ? { ...f.mend, turns: f.mend.turns - 1 } : null;
  }
  if (f.passive === 'sleepCycle') {
    if (!f.holdStage) f.stage = f.stage === 'deep' ? 'dream' : 'deep';
    if (f.stage === 'deep') heal(f, pn('sleepCycle', 'deepHeal'));
    f.echo = f.stage === 'dream';
  }
  if (f.passive === 'countingSheep' && f.stack) {
    drawExtra(f, f.stack, rng);
    f.stack = 0;
  }
  if (f.clock) {
    const card = f.table[f.clock];
    f.clock = null;
    play(fight, side, card, 1, rng, pn('minuteSlow', 'bonus'));
    if (fight.a.hp <= 0 || fight.d.hp <= 0) {
      fight.result = fight.a.hp <= 0 ? 'loss' : 'win';
      return false;
    }
  }
  drawCards(f, f.handLimit, rng);
  if (f.passive === 'bankedFire') {
    if (f.stack >= 3) {
      f.stack = 0;
      heal(f, pn('bankedFire', 'bellHeal'));
      f.skip = false;
      return false;
    }
    f.stack += 1;
  }
  if (f.skip) {
    f.skip = false;
    return false;
  }
  return true;
}

// --- Policies -------------------------------------------------------------

function affordable(f: Fighter) {
  return f.hand.filter((id, i) => f.hand.indexOf(id) === i && cost(f, id) <= f.energy);
}

function facePower(f: Fighter, c: Card) {
  return (c.power ?? 0) + (c.habit === f.setup.family ? 3 : 0);
}

/** Today's `chooseAI`, generalised: heal under 35 %, else the strongest attack, else a
 *  guard, else the biggest heal, else pass. Specials by a fixed rule. */
export function simplePolicy(fight: Fight, side: Side): Action {
  const f = fight[side];
  const ids = affordable(f).map((id) => f.table[id]);
  const fam = f.setup.family;
  let special = false;
  if (f.pips > 0 && !f.specialUsed) {
    if (fam === 'REST') special = f.hp < f.max * 0.5;
    if (fam === 'ROAM') special = f.energy < 2;
    if (fam === 'FOCUS') special = ids.some((c) => (c.power ?? 0) > 0);
  }
  const dream =
    f.passive === 'dream' &&
    !f.dreamUsed &&
    (fam === 'REST'
      ? f.hp < f.max * 0.5
      : fam === 'ROAM'
        ? f.energy < 2
        : ids.some((c) => (c.power ?? 0) > 0));
  if (special && fam === 'ROAM') {
    // Spend the refill on this turn's card choice.
    return { ...simpleCard(f, Math.min(3, f.energy + f.pips)), special: true, dream };
  }
  return { ...simpleCard(f, f.energy), special, dream };
}

function simpleCard(f: Fighter, budget: number): Action {
  const can = f.hand
    .filter((id, i) => f.hand.indexOf(id) === i && cost(f, id) <= budget)
    .map((id) => f.table[id]);
  if (f.hp < f.max * 0.35) {
    const heals = can
      .filter((c) => (c.heal ?? 0) > 0)
      .sort((a, b) => (b.heal ?? 0) - (a.heal ?? 0));
    if (heals.length) return { card: heals[0].id };
  }
  const attacks = can
    .filter((c) => (c.power ?? 0) > 0)
    .sort((a, b) => facePower(f, b) - facePower(f, a));
  if (attacks.length) return { card: attacks[0].id };
  const guard = can.find((c) => c.guard);
  if (guard) return { card: guard.id };
  const rest = can
    .filter((c) => c.special !== 'stardust')
    .sort((a, b) => (b.heal ?? 0) - (a.heal ?? 0));
  if (rest.length) return { card: rest[0].id };
  return { card: null };
}

function cloneFighter(f: Fighter): Fighter {
  return {
    ...f,
    hand: [...f.hand],
    draw: [...f.draw],
    discard: [...f.discard],
    mend: f.mend ? { ...f.mend } : null,
  };
}

function cloneFight(fight: Fight): Fight {
  let s = 0x9e3779b9;
  // Lookahead never consumes the real stream: a fixed local stream, rolls at the mean.
  const rng = () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
  return { ...fight, a: cloneFighter(fight.a), d: cloneFighter(fight.d), rng };
}

const stackValue: Partial<Record<PassiveId, number>> = {
  steady: 4.5,
  dim: 4,
  seep: 4.5,
  countingSheep: 3.5,
  bothy: 3,
  overgrow: 4,
  bankedFire: 0.5,
};

function score(fight: Fight, side: Side) {
  const me = fight[side];
  const foe = fight[side === 'a' ? 'd' : 'a'];
  if (foe.hp <= 0) return 10000;
  if (me.hp <= 0) return -10000;
  const hitSize = 10 + 2 * foe.setup.level;
  let s = -foe.hp;
  s += Math.min(me.hp, me.max * 0.5) * 1.2 + Math.max(0, me.hp - me.max * 0.5) * 0.45;
  s += 3 * Math.min(3, me.energy + 1 + me.nextEnergy);
  s += (me.passive ? (stackValue[me.passive] ?? 0) : 0) * me.stack;
  s += 0.3 * hitSize * me.guardHits;
  s += 3.5 * foe.spores + (me.dozed ? 0 : foe.spores * 1.5);
  s += 4 * foe.soak + 5 * foe.soften + (foe.skip ? hitSize : 0);
  if (me.clock)
    s +=
      ((me.table[me.clock].power ?? 0) + 2 * me.setup.level) * 1.4 + (me.table[me.clock].heal ?? 0);
  if (me.mend) s += me.mend.amount * me.mend.turns * 0.8;
  if (me.muteArmed) s += 3;
  if (me.reflectArmed) s += 5;
  s += 1.5 * Math.min(me.hand.length, 6);
  if (!me.specialUsed) s += 2 * me.pips;
  if (!me.dreamUsed && me.passive === 'dream') s += 3;
  return s;
}

/** One-ply lookahead with rolls at their mean: every affordable card (and Pendle's clock),
 *  pass, each with or without the special. The "best line" a careful player finds. */
export function smartPolicy(fight: Fight, side: Side): Action {
  const f = fight[side];
  const options: Action[] = [{ card: null }];
  const specialOpts = [false, ...(f.pips > 0 && !f.specialUsed ? [true] : [])];
  const dreamOpts = [false, ...(f.passive === 'dream' && !f.dreamUsed ? [true] : [])];
  for (const special of specialOpts)
    for (const dream of dreamOpts) {
      const energy =
        special && f.setup.family === 'ROAM'
          ? Math.min(3, f.energy + f.pips)
          : dream && f.setup.family === 'ROAM'
            ? Math.min(3, f.energy + 1)
            : f.energy;
      const ids = f.hand.filter((id, i) => f.hand.indexOf(id) === i && cost(f, id) <= energy);
      options.push({ card: null, special, dream });
      for (const id of ids) {
        options.push({ card: id, special, dream });
        if (f.passive === 'minuteSlow' && !f.clock)
          options.push({ card: id, clock: true, special, dream });
      }
    }
  let best = options[0];
  let bestScore = -Infinity;
  for (const o of options) {
    const sim = cloneFight(fight);
    const still = act(sim, side, o, () => 0.4);
    endTurn(sim, side, still);
    const v = score(sim, side);
    if (v > bestScore + 1e-9) {
      bestScore = v;
      best = o;
    }
  }
  return best;
}

export function runFight(fight: Fight) {
  const order: Side[] = ['a', 'd'];
  while (fight.result === null) {
    for (const side of order) {
      if (side === 'a' && fight.d.turns >= fight.rules.roundLimit) {
        fight.result = fight.rules.drawAtLimit ? 'draw' : 'loss';
        break;
      }
      const f = fight[side];
      const acts = beginTurn(fight, side);
      if (fight.result) break;
      // A lost turn (a doze, a skip, the bell) is not a still turn: nothing banks asleep.
      let still = false;
      if (acts) {
        const action =
          f.setup.policy === 'smart' || (f.setup.policy === 'casual' && fight.rng() >= 1 / 3)
            ? smartPolicy(fight, side)
            : simplePolicy(fight, side);
        still = act(fight, side, action);
      }
      endTurn(fight, side, still);
      if (fight.result) break;
    }
  }
  return {
    result: fight.result,
    turns: fight.a.turns,
    timedOut: fight.d.turns >= fight.rules.roundLimit && fight.a.hp > 0 && fight.d.hp > 0,
  };
}

// --- Set-ups for the report -----------------------------------------------

export function rivalSetup(r: Rival, playerFamily: Family, mirror: boolean): FighterSetup {
  return {
    name: r.id,
    family: r.family === 'mirror' ? (mirror ? playerFamily : 'ROAM') : r.family,
    level: r.level,
    zen: r.zen,
    deck: r.deck,
    passive: r.passive,
    pips: 0,
    policy: 'simple',
    mood: 50,
  };
}

export { familySpecies };
